# 방어: 복호화 전에 무결성 검증 + 오류 응답 통일
def decrypt_message(k_enc, k_mac, iv, ct, tag):
    # Encrypt-then-MAC: 패딩 검사보다 MAC 검증이 먼저
    expected = hmac_sha256(k_mac, iv + ct)
    if not constant_time_eq(tag, expected):
        raise DecryptError()  # 실패 사유를 구분하지 않음
    pt = cbc_decrypt(k_enc, iv, ct)
    if not valid_pkcs7(pt):
        raise DecryptError()  # 같은 오류·같은 응답 시간
    return strip_pkcs7(pt)

# 권장: AES-GCM 등 AEAD 사용 → 패딩 자체가 없음

command-injection.pseudocode:
# 취약: 입력을 셸 명령 문자열에 그대로 결합
def ping_bad(host):
    return shell_exec('ping -c 1 ' + host)
# 입력에 셸 메타문자가 섞이면 뒤 명령까지 실행됨

# 방어 1: 화이트리스트 검증 (IPv4 형식만 허용)
def is_valid_ip(host):
    parts = host.split('.')
    return len(parts) == 4 and all(
        p.isdigit() and 0 <= int(p) <= 255 for p in parts)

# 방어 2: 셸을 거치지 않고 인자 배열로 실행
def ping_safe(host):
    if not is_valid_ip(host):
        raise ValueError('잘못된 호스트')
    return exec_argv(['ping', '-c', '1', host])

injection-attack.pseudocode:
# 취약: 입력을 SQL 문자열에 직접 결합
def login_bad(db, uid, pw):
    q = ("SELECT * FROM users WHERE id='" + uid +
         "' AND pw='" + pw + "'")
    return db.query(q)
# 따옴표·주석 기호가 섞이면 조건 구조가 바뀜 → 인증 우회

# 안전: 파라미터 바인딩(입력은 데이터로만 취급)
def login_safe(db, uid, pw):
    q = "SELECT * FROM users WHERE id = ? AND pw = ?"
    return db.query(q, (uid, pw))
